import { createRoot } from 'react-dom/client';
import './index.css';
// Import React and necessary components from React Diagram library for building the diagram.
import * as React from "react";
import { HierarchicalTree, DataBinding, DiagramComponent, Inject, DiagramTools } from "@syncfusion/ej2-react-diagrams";
import { SampleBase } from './sample-base';
import { DataManager } from "@syncfusion/ej2-data";
export class RemoteData extends SampleBase {
    // Keep stable identities across renders
    dataManager;
    layout;
    getNodeDefaults;
    getConnectorDefaults;
    doBinding;
    dataSourceSettings;
    constructor(props) {
        super(props);
        // 1) Create DataManager once
        this.dataManager = new DataManager({
            url: "https://services.syncfusion.com/react/production/api/RemoteData",
            crossDomain: true
        });
        // 2) Create layout once
        this.layout = {
            type: "HierarchicalTree",
            margin: { left: 0, right: 0, top: 100, bottom: 0 },
            verticalSpacing: 40
        };
        // 3) Stable callbacks
        this.getNodeDefaults = (node) => {
            node.width = 80;
            node.height = 40;
            node.shape = { type: "Basic", shape: "Rectangle" };
            node.style = { fill: "#048785", strokeColor: "Transparent" };
        };
        this.getConnectorDefaults = (connector) => {
            connector.type = "Orthogonal";
            connector.style.strokeColor = "#048785";
            connector.targetDecorator.shape = "None";
        };
        this.doBinding = (nodeModel, data) => {
            nodeModel.annotations = [
                {
                    content: data["Label"],
                    style: { color: "white" }
                }
            ];
        };
        // 4) dataSourceSettings with stable identity
        this.dataSourceSettings = {
            id: "Id",
            parentId: "ParentId",
            dataSource: this.dataManager,
            doBinding: this.doBinding
        };
    }
    render() {
        return (<div className="control-pane">
                <div className="control-section">
                    <DiagramComponent id="diagram" width={"100%"} height={"490"} layout={this.layout} getNodeDefaults={this.getNodeDefaults} getConnectorDefaults={this.getConnectorDefaults} dataSourceSettings={this.dataSourceSettings} tool={DiagramTools.ZoomPan} snapSettings={{ constraints: 0 }}>
                        <Inject services={[DataBinding, HierarchicalTree]}/>
                    </DiagramComponent>
                </div>
            </div>);
    }
}

const root = createRoot(document.getElementById('sample'));
root.render(<RemoteData />);

